// First-party registry L7 (#2414): Workers Cache's purge, over the calling
// entrypoint's `ctx.cache` (the entry passes its `ctx`, so a purge reaches this
// Worker's own cache). Turning the cache on is the generated `[cache]` stanza,
// not here. With no `ctx.cache` (`bynk dev`, the bundle, an in-process caller)
// there is no edge cache to purge, so a purge logs and succeeds.
export class WorkersEdgeCache implements EdgeCache {
  private ctx?: unknown;
  constructor(ctx?: unknown) {
    this.ctx = ctx;
  }

  async purge(prefixes: readonly string[]): Promise<boolean> {
    for (const prefix of prefixes) {
      // A path, as Cloudflare takes one: no scheme, host, query or fragment.
      if (!prefix.startsWith("/") || /[\u0000-\u001f\u007f?#]/.test(prefix)) {
        throw new Error(
          `bynk.cloudflare.EdgeCache.purge takes paths starting with \`/\`, with no query, fragment or control characters; got ${JSON.stringify(prefix)}`,
        );
      }
    }
    if (prefixes.length === 0) return true;
    const cache = (this.ctx as { cache?: EdgeCachePurger } | undefined)?.cache;
    if (cache === undefined) {
      console.log("bynk: EdgeCache.purge is a no-op under bynk dev");
      return true;
    }
    const { success } = await cache.purge({ pathPrefixes: [...prefixes] });
    return success;
  }
}

// The part of the Workers `ExecutionContext.cache` the purge uses.
interface EdgeCachePurger {
  purge(options: { pathPrefixes: string[] }): Promise<{ success: boolean }>;
}

